"use strict";(self.webpackChunklightweight_charts_website=self.webpackChunklightweight_charts_website||[]).push([["82786"],{12601(n,e,t){t.r(e),t.d(e,{default:()=>o});let o="// remove-start\n// Lightweight Charts\u2122 Example: Crosshair modes\n// https://tradingview.github.io/lightweight-charts/examples/crosshair/crosshair-modes\n\n// remove-end\n// hide-start\nconst chartOptions = {\n	layout: {\n		textColor: CHART_TEXT_COLOR,\n		background: { type: 'solid', color: CHART_BACKGROUND_COLOR },\n	},\n	grid: {\n		vertLines: { color: CHART_GRID_COLOR },\n		horzLines: { color: CHART_GRID_COLOR },\n	},\n	// Fill the element the chart is created in, whatever its size.\n	autoSize: true,\n};\n// hide-end\nconst container = document.getElementById('container');\n// The chart takes the space above the buttons, which are added further down.\ncontainer.style.display = 'flex';\ncontainer.style.flexDirection = 'column';\nconst chartElement = document.createElement('div');\nchartElement.style.flex = '1';\nchartElement.style.minHeight = '0';\ncontainer.appendChild(chartElement);\n// remove-line\n/** @type {import('lightweight-charts').IChartApi} */\nconst chart = createChart(chartElement, chartOptions);\n\nconst series = chart.addSeries(CandlestickSeries, {\n	upColor: BAR_UP_COLOR,\n	downColor: BAR_DOWN_COLOR,\n	borderVisible: false,\n	wickUpColor: BAR_UP_COLOR,\n	wickDownColor: BAR_DOWN_COLOR,\n});\nseries.setData(generateBars());\nchart.timeScale().fitContent();\n\nfunction setMode(mode) {\n	// highlight-start\n	chart.applyOptions({ crosshair: { mode } });\n	// highlight-end\n}\n\n// hide-start\nconst styles = `\n    .buttons-container {\n        display: flex;\n        flex-direction: row;\n        flex-wrap: wrap;\n        gap: 8px;\n        padding: 8px;\n        background-color: ${CHART_BACKGROUND_COLOR};\n    }\n    .buttons-container button {\n        all: initial;\n        font-family: -apple-system, BlinkMacSystemFont, 'Trebuchet MS', Roboto, Ubuntu,\n            sans-serif;\n        font-size: 16px;\n        font-style: normal;\n        font-weight: 510;\n        line-height: 24px; /* 150% */\n        letter-spacing: -0.32px;\n        padding: 8px 24px;\n        color: ${BUTTON_TEXT_COLOR};\n        background-color: ${BUTTON_COLOR};\n        border-radius: 8px;\n        cursor: pointer;\n    }\n\n    .buttons-container button:hover {\n        background-color: ${BUTTON_HOVER_COLOR};\n    }\n\n    .buttons-container button:active {\n        background-color: ${BUTTON_ACTIVE_COLOR};\n    }\n`;\n\nconst stylesElement = document.createElement('style');\nstylesElement.innerHTML = styles;\ncontainer.appendChild(stylesElement);\n\nconst buttonsContainer = document.createElement('div');\nbuttonsContainer.classList.add('buttons-container');\n// hide-end\nconst modes = [\n	['Normal', CrosshairMode.Normal],\n	['Magnet', CrosshairMode.Magnet],\n	['Magnet OHLC', CrosshairMode.MagnetOHLC],\n	['Hidden', CrosshairMode.Hidden],\n];\nmodes.forEach(([label, mode]) => {\n	const button = document.createElement('button');\n	button.innerText = label;\n	button.addEventListener('click', () => setMode(mode));\n	buttonsContainer.appendChild(button);\n});\n\ncontainer.appendChild(buttonsContainer);\n\n// Start in magnet OHLC mode, which snaps to the nearest of the four prices.\nsetMode(CrosshairMode.MagnetOHLC);\n\n// Sample data: daily bars, a seeded random walk, so the chart looks the same\n// on every load.\nfunction generateBars(count = 60) {\n	let seed = 19;\n	const random = () => (seed = (seed * 16807) % 2147483647) / 2147483647;\n	const bars = [];\n	let time = Date.UTC(2024, 0, 1) / 1000;\n	let close = 100;\n	for (let i = 0; i < count; i++) {\n		const open = close;\n		close = open + (random() - 0.48) * 4;\n		const high = Math.max(open, close) + random() * 2;\n		const low = Math.min(open, close) - random() * 2;\n		bars.push({ time, open, high, low, close });\n		time += 24 * 60 * 60;\n	}\n	return bars;\n}\n"}}]);